class AssemblyAssemblyOperation(TypedDict):
    """One assembly operation. An installation step puts `part` into `into` along `direction` (in the receiving part's model frame) until the acceptance holds; the fit, insert or ring comes from the interface limit of the same kind. predecessors name the operations that must come first, closes the parts it encloses, and tool_access the tools that must reach. A tool name alone is display text: its reach stays unknown. path, when given, is the part's insertion path; without it the part travels in a straight line along direction, and checks report that default. edge_distance is a fastener, insert or heat-set joint's distance from its hole to the nearest edge against its sourced criterion

    Source: skills/cad-record/schemas/assembly.schema.json#/$defs/assembly_operation

    Not expressible as types (see the schema):
    - additionalProperties: false
    - if {"properties":{"kind":{"enum":["press_fit","heat_set","retaining_ring"]}}} then {"required":["into","interface","direction","acceptance"]}
    - if {"properties":{"kind":{"enum":["insert","fasten","join"]}}} then {"required":["into","direction","acceptance"]}
    - if {"properties":{"kind":{"const":"close"}}} then {"required":["into","closes"]}
    - if {"properties":{"kind":{"enum":["adjust","inspect"]}}} then {"required":["acceptance"]}
    - if {"properties":{"kind":{"const":"disassemble"}}} then {"required":["into","direction"]}
    - if {"properties":{"kind":{"enum":["close","adjust","inspect","disassemble"]}}} then {"not":{"required":["edge_distance"]}}
    - if {"required":["path"]} then {"required":["direction"],"properties":{"kind":{"enum":["press_fit","heat_set","retaining_ring","insert","fasten","join","close"]}}}

    Field notes:
    - id: pattern: "^[a-z][a-z0-9_-]*$"
    - interface: pattern: "^IF-[0-9]{3}$"
    - tools: items.minLength: 1
    - consumables: items.minLength: 1
    - verify_joint: pattern: "^J-[0-9]{3}$"
    - predecessors: minItems: 1; uniqueItems: true; items.pattern: "^[a-z][a-z0-9_-]*$"
    - closes: parts this operation encloses: no later operation reaches them; minItems: 1; uniqueItems: true
    - tool_access: minItems: 1
    - edge_distance: The joint's edge distance: the criterion it must meet (property edge_distance, a length bound with its source) and the distance the design gives, a known length (an interval's lower end governs) or an unknown with its reason
    - path: The insertion path of `part`: its offsets in mm from the installed pose, in the receiving part's model frame, keeping the installed orientation. The part starts at start, passes via in order and arrives installed; the last leg runs along direction
    - inspection: minLength: 1
    """
    id: Required[str]
    kind: Required[Literal["press_fit", "heat_set", "retaining_ring", "insert", "fasten", "join", "close", "adjust", "inspect", "disassemble"]]
    part: Required[AssemblyPartRef]
    into: NotRequired[AssemblyPartRef]
    interface: NotRequired[str]
    direction: NotRequired[AssemblyVector]
    acceptance: NotRequired[AssemblyAssemblyOperationAcceptance]
    tools: NotRequired[list[str]]
    consumables: NotRequired[list[str]]
    verify_joint: NotRequired[str]
    predecessors: NotRequired[list[str]]
    closes: NotRequired[list[AssemblyPartRef]]
    tool_access: NotRequired[list[AssemblyAssemblyOperationToolAccessItems]]
    engagement: NotRequired[ManufacturingQuantityFact]
    torque: NotRequired[ManufacturingQuantityFact]
    retention: NotRequired[ManufacturingTextFact]
    service_access: NotRequired[ManufacturingTextFact]
    edge_distance: NotRequired[AssemblyAssemblyOperationEdgeDistance]
    path: NotRequired[AssemblyAssemblyOperationPath]
    inspection: NotRequired[str]


