class ConceptScene(TypedDict):
    """CAD L0 concept scene

    Rough visual concept: 1-4 live variants built from primitives, rendered side by side by the cad-concept viewer. Z is up, lengths are mm, rotations are XYZ Euler degrees. Cross-field rules (unique ids, joint wiring, limit order) are checked by scripts/concept.py check.

    Source: skills/cad-concept/assets/schemas/concept-scene.schema.json#

    Not expressible as types (see the schema):
    - additionalProperties: false

    Field notes:
    - title: minLength: 1
    - chosen: Variant id the user approved at the VARIANT gate. Absent until then.
    - variants: minItems: 1; maxItems: 4
    - retired: Variants removed by a drop or merge, kept for the design record. Not rendered.
    """
    format: Required[Literal["cad.concept-scene"]]
    version: Required[Literal[1]]
    id: Required[ConceptSceneId]
    title: Required[str]
    units: Required[Literal["mm"]]
    notes: NotRequired[str]
    chosen: NotRequired[ConceptSceneId]
    variants: Required[list[ConceptSceneVariant]]
    retired: NotRequired[list[ConceptSceneRetired]]


